package dev.chyken.assembl_ar.camera;
import java.util.*;import java.nio.file.*;import org.junit.Test;import static org.junit.Assert.*;import dev.chyken.assembl_ar.vision.*;
public final class Phase11AssetCatalogTest {
    @Test public void actualRawFoldersAndRequestedAliasesHaveCompleteMapping()throws Exception{List<String> paths=new ArrayList<>();try(java.util.stream.Stream<Path> files=Files.walk(Paths.get("src/main/assets/references/Phase11"))){files.filter(Files::isRegularFile).forEach(p->paths.add(p.toString().replace('\\','/').substring("src/main/assets/".length())));}List<ComponentReferenceSpec> all=Phase11AssetCatalog.referencesForPaths(paths);int reviewed=0;int[] expected={19,14,15};for(ComponentReferenceSpec s:Phase1011VideoReferences.all())if(s.getAssemblyStepNumber()==11){reviewed++;for(int i=0;i<3;i++)if(Phase11AssetCatalog.eligible(Phase11AssetCatalog.referenceRole(s.getReferenceId()),i+1))expected[i]++;}assertEquals(48+reviewed,all.size());int[] counts=new int[3];for(ComponentReferenceSpec s:all){assertEquals(11,s.getAssemblyStepNumber());assertTrue(Files.isRegularFile(Paths.get("src/main/assets",s.getJpegAssetPath())));for(int i=0;i<3;i++)if(Phase11AssetCatalog.eligible(Phase11AssetCatalog.referenceRole(s.getReferenceId()),i+1))counts[i]++;}assertArrayEquals(expected,counts);for(int i=0;i<2;i++)assertEquals(1,Phase11AssetCatalog.videosForPaths(paths,i).size());for(int i=1;i<=3;i++)assertNotNull(Phase11AssetCatalog.guideForPaths(paths,i));assertEquals("front",Phase11AssetCatalog.role("STEP11_1OLEDDISPLAYSCAN"));assertEquals("battery",Phase11AssetCatalog.role("STEP11_2BATTERYSCAN"));assertEquals("assembly",Phase11AssetCatalog.role("STEP11_3OLED_MOUNTED_TOPVIEW"));}
    @Test public void requestCopyAndScopeKeepFlipEvidenceWithoutUnrelatedAssets(){List<ComponentReferenceSpec> all=Phase11AssetCatalog.referencesForPaths(Arrays.asList("references/Phase11/STEP11_1OLEDSCAN/a.jpg","references/Phase11/STEP11_1OLEDSCANINVALID/b.jpg","references/Phase11/STEP11_2BATTERYPACKSCAN/c.jpg","references/Phase11/P11_SCANNINGGUIDE/guide.jpg"));RecognitionRequest r=new RecognitionRequest(RecognitionRequest.AssemblyExpectation.component(Phase11AssetCatalog.target(1)),null,null,null,1,11).withPhase11Stage(1).withRequestTag("new");assertEquals(1,r.getPhase11Stage());assertEquals(2,ActiveReferenceScope.select(all,r).size());assertEquals("p11:2",ActiveReferenceScope.key(ActiveReferenceScope.next(r)));assertNull(ActiveReferenceScope.next(new RecognitionRequest(RecognitionRequest.AssemblyExpectation.component(Phase11AssetCatalog.target(3)),null,null,null,1,11).withPhase11Stage(3)));}
    @Test public void nextBankRouteReachesEveryAuthoredScanOnce(){RecognitionRequest r=new RecognitionRequest(RecognitionRequest.AssemblyExpectation.component("main_board"),null,null,null,1,1);Set<String> keys=new HashSet<>();while(r!=null){assertTrue(keys.add(ActiveReferenceScope.key(r)));r=ActiveReferenceScope.next(r);}assertEquals(24,keys.size());assertFalse(keys.contains("p9:1"));}
}
